#include "generated_loop_repair_fixtures.h"
#include "SketchPlaneRepair.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
using MultiFaceFixtures::check;
int main(int argc,char** argv){QCoreApplication app(argc,argv);try {
 QTemporaryDir folder;const auto ids=GeneratedLoopRepairFixtures::create(folder.path());CadDocument doc;check(doc.open(folder.path()+"/generated-loop-repair.alloy").isEmpty(),"fixture open");const auto before=doc.authored();const auto sketchId=ids.value("sketchId").toString();const auto original=SketchGeometry::findFeature(before,sketchId);const auto oldProfile=doc.sketches().back().profiles.front();
 auto failure=[&](const QString& tool){return CadDocument::booleanCandidate(before,{{"featureId",ids.value("combineFeatureId")},{"targetBodyId",ids.value("targetBodyId")},{"toolBodyIds",QJsonArray{ids.value(tool)}},{"operation","cut"},{"keepTools",true}});};
 const auto failed=failure("deleteBodyId");check(!doc.commit(failed,"Lose support").isEmpty() && doc.lastEvaluationError().value("code")=="support_unavailable","missing support diagnostic");check(doc.authored()==before,"failure atomic");
 auto prefix=failed;QJsonArray rows;for(const auto& f:failed.value("features").toArray()){if(f.toObject().value("id")==sketchId)break;rows.append(f);}prefix["features"]=rows;const auto evaluated=CadDocument::evaluateCandidate(prefix);check(evaluated.ok,"prefix");const auto frame=GeometryKernel::sketchFrame(doc.evaluationBefore(sketchId),original);
 QSet<QString> oldIds{oldProfile.profileId};for(const auto& edge:oldProfile.boundaryEdges){oldIds.insert(edge.sourceEntityId);oldIds.insert(edge.startContact);oldIds.insert(edge.endContact);}
 const QJsonObject replacement{{"support",ids.value("replacementSupport")},{"distanceMm",-1}};
 const auto changed=SketchPlaneRepair::recreateInset(failed,*evaluated.evaluation,sketchId,replacement,frame,oldIds);auto repaired=SketchGeometry::findFeature(changed.authored,sketchId);auto expected=original;auto p=expected.value("parameters").toObject();p["support"]=ids.value("replacementSupport");p["loopOffsets"]=repaired.value("parameters").toObject().value("loopOffsets");expected["parameters"]=p;check(repaired==expected,"unaffected data stable");
 const auto owner=p.value("loopOffsets").toArray().first().toObject();const auto oldOwner=original.value("parameters").toObject().value("loopOffsets").toArray().first().toObject();check(owner.value("id")!=oldOwner.value("id") && owner.value("outerLoopId")!=oldOwner.value("outerLoopId"),"fresh identities");const auto preview=CadDocument::evaluateCandidate(changed.authored);check(preview.ok,preview.error);const auto profile=preview.evaluation->sketches.back().profiles.front();check(profile.profileId!=oldProfile.profileId && std::abs(profile.summary.value("areaMm2").toDouble()-874)<1e-6,"new target profile");for(const auto& edge:profile.boundaryEdges)for(const auto& old:oldProfile.boundaryEdges)check(edge.sourceEntityId!=old.sourceEntityId,"fresh edge identities");
 auto refuse=[&](const QJsonObject& candidate,const QJsonObject& choice,const QString& code){bool hit=false;try{SketchPlaneRepair::recreateInset(candidate,*evaluated.evaluation,sketchId,choice,frame,oldIds);}catch(const GeometryKernel::EvaluationError& e){hit=e.diagnostics().value("code")==code;}check(hit,code);check(doc.authored()==before,"refusal atomic");};
 refuse(failed,{{"plane","XY"},{"distanceMm",-1}},"offset_confirmation_required");refuse(failed,{{"support",ids.value("replacementSupport")}},"offset_confirmation_required");refuse(failed,{{"support",ids.value("support")},{"distanceMm",-1}},"distinct_support_required");
 const auto consumer=CadDocument::extrusionCandidate(before,{{"sketchId",sketchId},{"profileId",oldProfile.profileId},{"distanceMm",2}});auto failedConsumer=failed;auto fs=failed.value("features").toArray();fs.append(consumer.value("features").toArray().last());failedConsumer["features"]=fs;refuse(failedConsumer,replacement,"generated_profile_consumer");
 // Isolate a reference to a generated edge/contact without the sketch/profile UUID.
 for(const auto& reference:{oldProfile.boundaryEdges.front().sourceEntityId,oldProfile.boundaryEdges.front().startContact}){auto edgeConsumer=failed;auto rows=failed.value("features").toArray();rows.append(QJsonObject{{"id",CadDocument::newId()},{"parameters",QJsonObject{{"edgeId",reference}}}});edgeConsumer["features"]=rows;refuse(edgeConsumer,replacement,"generated_profile_consumer");}
 const auto incomplete=CadDocument::evaluateCandidate(failure("splitBodyId"));check(!incomplete.ok && incomplete.diagnostics.value("code")=="ambiguous_inset_lineage","incomplete regression");
 auto same=before;auto extrude=before.value("features").toArray().at(1).toObject();auto ep=extrude.value("parameters").toObject();ep["distanceMm"]=6;extrude["parameters"]=ep;same=GeneratedLoopRepairFixtures::replaceRow(same,extrude);const auto recomputed=CadDocument::evaluateCandidate(same);check(recomputed.ok && SketchGeometry::findFeature(recomputed.authored,sketchId)==original && recomputed.evaluation->sketches.back().profiles.front().profileId==oldProfile.profileId,"same-boundary identity");
 check(doc.commit(changed.authored,"Recreate Offset").isEmpty(),"aggregate commit");const auto after=doc.authored();doc.history().undo();check(doc.authored()==before,"undo exact");doc.history().redo();check(doc.authored()==after,"redo exact");check(doc.save(folder.path()+"/repaired.alloy").isEmpty(),"save");CadDocument reopen;check(reopen.open(folder.path()+"/repaired.alloy").isEmpty() && reopen.authored()==after,"reopen exact");std::cout<<"PASS generated distinct-face recreation, fresh IDs, local data, consumers, same/incomplete/missing, history and reopen\n";
 return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
